<?php if($id>0&&$ticket): ?><section class="panel customer-form-panel"><div class="panel-head"><div><h2><?= kd_e($ticket['ticket_number']) ?> · <?= kd_e($ticket['subject']) ?></h2><p class="muted"><?= kd_e($ticket['customer_name']??'Müşteri belirtilmedi') ?></p></div><a class="btn secondary action-link" href="index.php?page=support">Listeye dön</a></div><form method="post" class="support-update"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="update"><input type="hidden" name="ticket_id" value="<?= (int)$ticket['id'] ?>"><label>Durum<select name="status"><?php foreach(['open'=>'Açık','in_progress'=>'İşlemde','waiting'=>'Yanıt bekliyor','closed'=>'Kapalı'] as $k=>$v): ?><option value="<?= $k ?>" <?= $ticket['status']===$k?'selected':'' ?>><?= $v ?></option><?php endforeach; ?></select></label><label>Öncelik<select name="priority"><?php foreach(['low'=>'Düşük','normal'=>'Normal','high'=>'Yüksek','urgent'=>'Acil'] as $k=>$v): ?><option value="<?= $k ?>" <?= $ticket['priority']===$k?'selected':'' ?>><?= $v ?></option><?php endforeach; ?></select></label><label>Atanan personel<select name="assigned_user_id"><option value="0">Atanmamış</option><?php foreach($users as $u): ?><option value="<?= (int)$u['id'] ?>" <?= (int)$ticket['assigned_user_id']===(int)$u['id']?'selected':'' ?>><?= kd_e($u['name']) ?></option><?php endforeach; ?></select></label><button class="btn secondary">Kaydet</button></form><div class="support-thread"><h3>Konuşma geçmişi</h3><?php foreach($messages as $m): ?><article class="support-message <?= $m['is_internal']?'internal':'' ?>"><strong><?= kd_e($m['user_name']??'Sistem') ?> <?= $m['is_internal']?'· İç not':'' ?></strong><p><?= nl2br(kd_e($m['message'])) ?></p><small><?= kd_e($m['created_at']) ?></small></article><?php endforeach; ?></div><form method="post" class="support-reply"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="message"><input type="hidden" name="ticket_id" value="<?= (int)$ticket['id'] ?>"><label>Yanıt / not<textarea name="message" rows="4" required></textarea></label><label><input type="checkbox" name="is_internal" value="1"> İç not (müşteriye gösterilmez)</label><button class="btn primary">Yanıt ekle</button></form></section>
<?php else: ?><div class="marketplace-grid"><section class="panel customer-form-panel"><h3>Yeni destek talebi</h3><form method="post"><?= kd_csrf_field() ?><input type="hidden" name="form_action" value="create"><label>Müşteri<select name="customer_id"><option value="0">Müşteri seçilmedi</option><?php foreach($customers as $c): ?><option value="<?= (int)$c['id'] ?>"><?= kd_e($c['name']) ?></option><?php endforeach; ?></select></label><label>Konu<input name="subject" maxlength="190" required></label><label>Açıklama<textarea name="description" rows="4" required></textarea></label><label>Öncelik<select name="priority"><option value="normal">Normal</option><option value="high">Yüksek</option><option value="urgent">Acil</option><option value="low">Düşük</option></select></label><label>Atanan personel<select name="assigned_user_id"><option value="0">Atanmamış</option><?php foreach($users as $u): ?><option value="<?= (int)$u['id'] ?>"><?= kd_e($u['name']) ?></option><?php endforeach; ?></select></label><button class="btn primary">Talep oluştur</button></form></section><section class="panel customer-list-panel"><div class="panel-head"><h3>Destek talepleri</h3><span class="result-count"><?= count($tickets) ?> kayıt</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Talep</th><th>Müşteri</th><th>Öncelik</th><th>Durum</th><th>Atanan</th><th></th></tr></thead><tbody><?php foreach($tickets as $t): ?><tr><td><strong><?= kd_e($t['ticket_number']) ?></strong><small class="table-sub"><?= kd_e($t['subject']) ?></small></td><td><?= kd_e($t['customer_name']??'—') ?></td><td><?= kd_e($t['priority']) ?></td><td><?= kd_e($t['status']) ?></td><td><?= kd_e($t['assignee_name']??'—') ?></td><td><a class="btn secondary action-link" href="index.php?page=support&id=<?= (int)$t['id'] ?>">Aç</a></td></tr><?php endforeach; ?><?php if(!$tickets): ?><tr><td colspan="6">Destek talebi bulunmuyor.</td></tr><?php endif; ?></tbody></table></div></section></div><?php endif; ?>
